import React, { useEffect, useState } from 'react';
import { connectToNakama } from './api'; // Use your API file as the single source

function App() {
  const [socket, setSocket] = useState(null);
  const [gameState, setGameState] = useState(null);
  const [matchId, setMatchId] = useState(null);
  const [myId, setMyId] = useState("");
  const [searching, setSearching] = useState(false);

  useEffect(() => {
    // Only run this ONCE when the app loads
    connectToNakama().then(({ session, socket }) => {
      setSocket(socket);
      setMyId(session.user_id);

      // Listener: When matchmaker finds an opponent
      socket.onmatchmakermatched = async (matched) => {
        const match = await socket.joinMatch(null, matched.token);
        setMatchId(match.id);
        setSearching(false);
      };

      // Listener: Server-authoritative state updates
      socket.onmatchdata = (result) => {
        const data = JSON.parse(new TextDecoder().decode(result.data));
        setGameState(data);
      };
    }).catch(err => console.error("Nakama Connection Failed:", err));
  }, []);

  const findGame = () => {
    setSearching(true);
    // Tell Nakama to find exactly 2 players
    socket.addMatchmaker("*", 2, 2); 
  };

  const makeMove = (index) => {
    // 1. Check if it's actually our turn (Server validates this too, but UX is better this way)
    // 2. Check if cell is empty
    // 3. Ensure no winner yet
    if (!matchId || !gameState || gameState.winner) return;
    if (gameState.currentTurn !== myId) return;
    if (gameState.board[index] !== "") return;

    // Send move to backend index.js (OpCode 1)
    const payload = JSON.stringify({ cell: index });
    socket.sendMatchState(matchId, 1, payload); 
  };

  // UI STATE 1: Not in a game yet
  if (!matchId) {
    return (
      <div className="lobby">
        <h1>Multiplayer Tic-Tac-Toe</h1>
        <button onClick={findGame} disabled={searching}>
          {searching ? "Searching for Opponent..." : "Find Match"}
        </button>
      </div>
    );
  }

  // UI STATE 2: Match joined, but waiting for backend state
  if (!gameState) {
    return <div className="loading">Initializing Game...</div>;
  }

  // UI STATE 3: The Game Board
  return (
    <div className="game-container">
      <h2>
        {gameState.winner 
          ? (gameState.winner === "draw" ? "It's a Draw!" : `Winner: ${gameState.winner === 'X' ? 'Player X' : 'Player O'}`)
          : (gameState.currentTurn === myId ? "YOUR TURN" : "OPPONENT'S TURN")
        }
      </h2>

      <div className="grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 100px)', gap: '5px' }}>
        {gameState.board.map((cell, i) => (
          <button 
            key={i} 
            className={`cell ${cell}`} 
            onClick={() => makeMove(i)}
            style={{ width: '100px', height: '100px', fontSize: '24px' }}
          >
            {cell}
          </button>
        ))}
      </div>

      {gameState.winner && (
        <button onClick={() => window.location.reload()}>Play Again</button>
      )}
    </div>
  );
}

export default App;
